-- Q05 · Matriz de acesso direto: anon / autenticado sem papel / tester / admin / servidor.
-- Na base de dados, 'sem papel', 'tester' e 'admin' são todos o papel authenticated; só a barreira
-- (has_staging_access) os distingue. Sem permissões diretas, nenhum dos três chega às tabelas/funções V2.
-- LIMITE: isto prova privilégios da BASE. service_role ignora a barreira (BYPASSRLS): a segurança funcional
-- depende de APIs de servidor que verifiquem sessão + has_staging_access, e essas APIs AINDA NÃO EXISTEM (B3).
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH v2 AS (SELECT unnest(ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[]) AS nome),
t2 AS (SELECT c.oid, c.relname::text AS nome, c.relacl, c.relowner, c.relrowsecurity, c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace JOIN v2 ON v2.nome = c.relname::text WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')),
f2 AS (SELECT p.oid, p.proname::text AS nome, p.proacl, p.proowner, p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname::text = ANY (ARRAY['access_invites_pilot_guard', 'account_access_on_new_profile', 'audit_sensitive_write', 'claim_inbound_message', 'claim_pending_confirmation', 'consultant_preferences_track_opt_ins', 'consume_access_invite', 'content_access_consents_validate', 'conversation_states_touch', 'daily_digests_validate', 'effective_tier', 'email_drafts_validate', 'expire_beta_testers', 'is_admin', 'issue_pilot_invite', 'issue_referral_invite', 'mark_pending_presented', 'pending_actions_validate', 'people_touch_email_norm', 'pilot_participant_on_invite_used', 'pilot_participants_guard', 'plan_configs_validate', 'product_feedback_validate', 'product_updates_validate', 'profiles_restrict_self_update', 'profiles_validate_billing', 'purge_admin_audit_logs', 'release_conversation_lock', 'release_pending_confirmation', 'release_unsolicited_slot', 'reminders_sync_follow_up_id', 'reserve_unsolicited_slot', 'revoke_pilot_invite', 'set_updated_at', 'subscription_events_validate', 'text_norm', 'tier_at_least', 'try_acquire_conversation_lock']::text[])),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q05-01'::text, 'anon · tabelas V2 com algum acesso direto'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE')) = 0)::boolean, '0'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE'))::text)::text
  UNION ALL SELECT 'Q05-02'::text, 'anon · funções V2 executáveis'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE')) = 0)::boolean, '0'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE'))::text)::text
  UNION ALL SELECT 'Q05-03'::text, 'authenticated sem papel / tester / admin · tabelas V2 com algum acesso direto'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE')) = 0)::boolean, '0'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE'))::text)::text
  UNION ALL SELECT 'Q05-04'::text, 'authenticated sem papel / tester / admin · funções V2 executáveis'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('authenticated', oid, 'EXECUTE')) = 0)::boolean, '0'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('authenticated', oid, 'EXECUTE'))::text)::text
  UNION ALL SELECT 'Q05-05'::text, 'barreira: tabelas V2 em que anon/authenticated sem admin/tester são negados mesmo que um dia recebam permissão'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.roles = ARRAY['anon', 'authenticated']::name[]) = 104)::boolean, '104'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.roles = ARRAY['anon', 'authenticated']::name[])::text)::text
  UNION ALL SELECT 'Q05-06'::text, 'tester/admin: a barreira usa a função do staging, inalterada e executável por authenticated'::text, ((SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'has_staging_access') = '4376edeea92abf14230207df0fbbef11' AND has_function_privilege('authenticated', 'public.has_staging_access(uuid)', 'EXECUTE'))::boolean, 'sim'::text, (has_function_privilege('authenticated', 'public.has_staging_access(uuid)', 'EXECUTE')::text)::text
  UNION ALL SELECT 'Q05-07'::text, 'admin do staging NÃO é admin V2 (nenhum super_admin/support_admin)'::text, (NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role::text IN ('super_admin', 'support_admin')))::boolean, '0'::text, ((SELECT count(*) FROM public.user_roles WHERE role::text IN ('super_admin', 'support_admin'))::text)::text
  UNION ALL SELECT 'Q05-08'::text, 'service_role · tabelas V2 com exatamente SELECT/INSERT/UPDATE/DELETE (sem TRUNCATE/REFERENCES/TRIGGER)'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE') AND NOT has_table_privilege('service_role', oid, 'TRUNCATE,REFERENCES,TRIGGER')) = 104)::boolean, '104'::text, ((SELECT count(*) FROM t2 WHERE has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE') AND NOT has_table_privilege('service_role', oid, 'TRUNCATE,REFERENCES,TRIGGER'))::text)::text
  UNION ALL SELECT 'Q05-09'::text, 'service_role · funções V2 executáveis'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('service_role', oid, 'EXECUTE')) = 38)::boolean, '38'::text, ((SELECT count(*) FROM f2 WHERE has_function_privilege('service_role', oid, 'EXECUTE'))::text)::text
  UNION ALL SELECT 'Q05-10'::text, 'storage e Realtime · superfícies V2 abertas a clientes'::text, (NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%')) AND NOT EXISTS (SELECT 1 FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public'))::boolean, 'nenhuma'::text, ('storage=' || (SELECT count(*) FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%'))::text || ', realtime=' || (SELECT count(*) FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public')::text)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 10 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
